### 2.3 `stress.js` (independent cross‑checks)

```js
'use strict';
/* Extra stress / cross-validation for hull3d.js */

const assert = require('assert');
const H = require('./hull3d');

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* ---------- BigInt reference determinants ---------- */
function big3(a, b, c, d, e, f, g, h, i) {
  return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}
function big4(m) {
  const a = m[0][0], b = m[0][1], c = m[0][2], d = m[0][3];
  const A = big3(m[1][1], m[1][2], m[1][3], m[2][1], m[2][2], m[2][3], m[3][1], m[3][2], m[3][3]);
  const B = big3(m[1][0], m[1][2], m[1][3], m[2][0], m[2][2], m[2][3], m[3][0], m[3][2], m[3][3]);
  const C = big3(m[1][0], m[1][1], m[1][3], m[2][0], m[2][1], m[2][3], m[3][0], m[3][1], m[3][3]);
  const D = big3(m[1][0], m[1][1], m[1][2], m[2][0], m[2][1], m[2][2], m[3][0], m[3][1], m[3][2]);
  return a * A - b * B + c * C - d * D;
}
const sgn = (d) => (d > 0n ? 1 : d < 0n ? -1 : 0);

function incircleRef(a, b, c, d) {
  const ax = BigInt(a.x) - BigInt(d.x), ay = BigInt(a.y) - BigInt(d.y);
  const bx = BigInt(b.x) - BigInt(d.x), by = BigInt(b.y) - BigInt(d.y);
  const cx = BigInt(c.x) - BigInt(d.x), cy = BigInt(c.y) - BigInt(d.y);
  const al = ax * ax + ay * ay, bl = bx * bx + by * by, cl = cx * cx + cy * cy;
  return sgn(big3(ax, ay, al, bx, by, bl, cx, cy, cl));
}
function insphereRef(a, b, c, d, e) {
  const mk = (p) => {
    const x = BigInt(p.x) - BigInt(e.x), y = BigInt(p.y) - BigInt(e.y), z = BigInt(p.z) - BigInt(e.z);
    return [x, y, z, x * x + y * y + z * z];
  };
  return sgn(big4([mk(a), mk(b), mk(c), mk(d)]));
}

/* ---------- brute force boundary points (all points on some supporting plane) ---------- */
function bruteBoundary(pts) {
  const n = pts.length;
  const bd = new Set();
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) for (let k = j + 1; k < n; k++) {
    const A = pts[i], B = pts[j], C = pts[k];
    if (H.collinearExact(A, B, C)) continue;
    let pos = false, neg = false;
    for (let q = 0; q < n; q++) {
      const s = H.orient3d(A, B, C, pts[q]);
      if (s > 0) pos = true; else if (s < 0) neg = true;
      if (pos && neg) break;
    }
    if (!(pos && neg)) { bd.add(i); bd.add(j); bd.add(k); }
  }
  return bd;
}

/* ============================================================= */
let fails = 0;
function check(cond, msg) { if (!cond) { console.error('FAIL: ' + msg); fails++; } }

/* 1) incircle / insphere vs BigInt reference */
(function () {
  const rnd = mulberry32(555);
  const RI = (lo, hi) => Math.floor(rnd() * (hi - lo + 1)) + lo;
  let incBad = 0, sphBad = 0;
  for (let t = 0; t < 50000; t++) {
    const a = { x: RI(-1000, 1000), y: RI(-1000, 1000) };
    const b = { x: RI(-1000, 1000), y: RI(-1000, 1000) };
    const c = { x: RI(-1000, 1000), y: RI(-1000, 1000) };
    const d = { x: RI(-1000, 1000), y: RI(-1000, 1000) };
    if (H.incircle(a, b, c, d) !== incircleRef(a, b, c, d)) incBad++;

    const A = { x: RI(-100, 100), y: RI(-100, 100), z: RI(-100, 100) };
    const B = { x: RI(-100, 100), y: RI(-100, 100), z: RI(-100, 100) };
    const C = { x: RI(-100, 100), y: RI(-100, 100), z: RI(-100, 100) };
    const D = { x: RI(-100, 100), y: RI(-100, 100), z: RI(-100, 100) };
    const E = { x: RI(-100, 100), y: RI(-100, 100), z: RI(-100, 100) };
    if (H.insphere(A, B, C, D, E) !== insphereRef(A, B, C, D, E)) sphBad++;
  }
  check(incBad === 0, 'incircle mismatches: ' + incBad);
  check(sphBad === 0, 'insphere mismatches: ' + sphBad);
  console.log('incircle/insphere verified (50000 each), mismatches:', incBad, sphBad);
})();

/* 2) independent boundary coverage on random small integer sets. */
(function () {
  const rnd = mulberry32(31337);
  const RI = (lo, hi) => Math.floor(rnd() * (hi - lo + 1)) + lo;
  let checked = 0, bad = 0;
  for (let t = 0; t < 400; t++) {
    const n = RI(4, 22);
    const range = [3, 5, 10][t % 3];
    const raw = [];
    for (let i = 0; i < n; i++) raw.push({ x: RI(-range, range), y: RI(-range, range), z: RI(-range, range) });
    const hull = H.buildHull(raw);
    if (hull.dimension !== 3) continue;
    checked++;
    const ref = bruteBoundary(hull.uniquePoints);
    const pts = hull.uniquePoints;
    for (const qi of ref) {
      let onFacet = false;
      for (const f of hull.facets) {
        const [a, b, c] = f.v;
        if (H.orient3d(pts[a], pts[b], pts[c], pts[qi]) === 0) { onFacet = true; break; }
      }
      if (!onFacet) {
        bad++;
        console.error('  boundary point', qi, 'not covered by any facet (set', t, ')');
      }
    }
    const r = H.checkInvariants(hull);
    if (!r.ok) { bad++; console.error('  invariant fail:', r.errors.slice(0, 3)); }
  }
  check(bad === 0, `boundary-coverage mismatches: ${bad}/${checked}`);
  console.log('boundary coverage vs brute force:', checked, 'sets, mismatches:', bad);
})();

/* 3) many degeneracy-heavy random sets: invariants only */
(function () {
  const rnd = mulberry32(4242);
  const RI = (lo, hi) => Math.floor(rnd() * (hi - lo + 1)) + lo;
  let dims = { 0: 0, 1: 0, 2: 0, 3: 0 }, bad = 0, total = 0;
  for (let t = 0; t < 600; t++) {
    const n = RI(1, 70);
    const mode = t % 5;
    const raw = [];
    for (let i = 0; i < n; i++) {
      let p;
      if (mode === 0) p = { x: RI(-2, 2), y: RI(-2, 2), z: RI(-2, 2) };
      else if (mode === 1) p = { x: RI(-100, 100), y: RI(-100, 100), z: 0 };
      else if (mode === 2) p = { x: RI(-100, 100), y: RI(-100, 100), z: i % 2 ? 0 : 5 };
      else if (mode === 3) p = { x: i, y: 0, z: 0 };
      else p = { x: RI(-50, 50), y: RI(-50, 50), z: RI(-50, 50) };
      raw.push(p);
      if (rnd() < 0.15) raw.push({ ...p });
    }
    const hull = H.buildHull(raw);
    total++;
    dims[hull.dimension >= 0 ? hull.dimension : 0]++;
    const r = H.checkInvariants(hull);
    if (!r.ok) { bad++; if (bad <= 5) console.error('  invariant fail (mode', mode, '):', r.errors.slice(0, 2)); }
  }
  check(bad === 0, `degeneracy stress invariant failures: ${bad}/${total}`);
  console.log('degeneracy stress:', total, 'sets, failures:', bad, ', dims:', JSON.stringify(dims));
})();

/* 4) 3D hull with extra points exactly on faces and edges */
(function () {
  const raw = [];
  for (const x of [0, 1, 2]) for (const y of [0, 1, 2]) for (const z of [0, 1, 2]) {
    if (x === 0 || x === 2 || y === 0 || y === 2 || z === 0 || z === 2) raw.push({ x, y, z });
  }
  const hull = H.buildHull(raw);
  assert.strictEqual(hull.dimension, 3);
  const r = H.checkInvariants(hull);
  assert(r.ok, r.errors.join('\n'));
  assert.strictEqual(hull.vertices.length, 8, 'expected 8 corners, got ' + hull.vertices.length);
  assert.strictEqual(hull.facets.length, 6, 'expected 6 merged facets, got ' + hull.facets.length);
  console.log('cube with coplanar face/edge lattice points: ok (V=8, F=' + hull.facets.length + ')');
})();

/* 5) scale / performance sanity */
(function () {
  const rnd = mulberry32(7777);
  const raw = [];
  const N = 2000;
  for (let i = 0; i < N; i++) {
    const u = rnd() * 2 - 1, th = rnd() * 2 * Math.PI, s = Math.sqrt(1 - u * u);
    raw.push({ x: Math.cos(th) * s, y: u, z: Math.sin(th) * s });
  }
  const t0 = Date.now();
  const hull = H.buildHull(raw);
  const dt = Date.now() - t0;
  const r = H.checkInvariants(hull);
  assert(r.ok, r.errors.slice(0, 3).join('\n'));
  console.log(`sphere N=${N}: V=${hull.vertices.length} F=${hull.facets.length} in ${dt} ms`);
})();

console.log(fails === 0 ? '\nALL STRESS TESTS PASSED' : `\n${fails} STRESS FAILURES`);
process.exit(fails === 0 ? 0 : 1);
